package local.lito381.server;
import java.io.*;import java.nio.file.*;import java.util.*;
/** Exact frozen ConfigSkill property oracle versus original candidate validation; no files/SQL/services. */
public final class SourceSkillDefaultsPlan {
 static int cases,omissions,blanks,safety,compared;static void check(boolean b,String s){if(!b)throw new AssertionError(s);cases++;}
 static Properties damage(){var p=new Properties();for(var k:CombatRules.DAMAGE_KEYS)p.setProperty(k,"1");return p;}
 static void source(CombatRules.Snapshot s,Properties properties){var expected=SourceSkillConfigOracle.values(properties);int n=0;for(var key:CombatRules.SKILL_KEYS){if(NativeSourceSkillDefaults.value(key)==null)continue;if(key.endsWith("_TIMER")){for(var part:List.of("base","random")){var k=key+"."+part;if(!Objects.equals(s.values().get(k),expected.get(k)))throw new AssertionError("frozen Source "+k);compared++;}}else{if(!Objects.equals(s.values().get(key),expected.get(key)))throw new AssertionError("frozen Source "+key+" candidate="+s.values().get(key)+" Source="+expected.get(key));compared++;}n++;}check(n==31,"31 installed Source property keys compared, without three unused controls or unassigned Nature field");}
 static IOException invalid(Properties skill,Properties damage,Path p,boolean old)throws Exception{try{if(old)CombatRules.nativeSourceSkillDefaultsOriginalSnapshot(skill,damage,p,p);else CombatRules.snapshot(skill,damage,p,p);}catch(IOException expected){return expected;}throw new AssertionError("original unsafe input unexpectedly admitted");}
 public static void main(String[]args)throws Exception{
  var state=CombatRules.class.getDeclaredField("current");state.setAccessible(true);var prior=state.get(null);var p=Path.of("detached-no-Source-reader");var damage=damage();var full=SourceSkillConfigOracle.properties();
  try{var original=CombatRules.nativeSourceSkillDefaultsOriginalSnapshot(full,damage,p,p);var actual=CombatRules.snapshot(full,damage,p,p);check(original.equals(actual),"fully specified existing controls preserve original immutable snapshot values/metadata");source(actual,full);check(state.get(null)==prior,"snapshot preparation never publishes global controls");
   for(var key:CombatRules.SKILL_KEYS){if(NativeSourceSkillDefaults.value(key)==null)continue;
    for(var value:List.of("<missing>","","  \t  ")){var properties=new Properties();properties.putAll(full);if(value.equals("<missing>")){properties.remove(key);omissions++;}else{properties.setProperty(key,value);blanks++;}var before=new Properties();before.putAll(properties);var s=CombatRules.snapshot(properties,damage,p,p);source(s,properties);check(s.values().equals(original.values())&&s.defaultedKeys().contains(key),"Source omission/blank default and default metadata "+key);check(properties.equals(before)&&state.get(null)==prior,"original caller properties/global controls unchanged "+key);}
   }
   var empty=new Properties();var defaults=CombatRules.snapshot(empty,damage,p,p);source(defaults,empty);check(defaults.values().equals(original.values())&&empty.isEmpty(),"all installed optional skill controls may be omitted using exact Source defaults");var blank=new Properties();for(var k:CombatRules.SKILL_KEYS)blank.setProperty(k," \t ");var blankSnapshot=CombatRules.snapshot(blank,damage,p,p);source(blankSnapshot,blank);check(blankSnapshot.values().equals(original.values()),"all installed optional skill controls may be blank without mutating input");
   var overridden=SourceSkillConfigOracle.properties();overridden.setProperty("CURSE_READY_TIME","7");overridden.setProperty("BURNING_DMG","2.0");overridden.setProperty("SHOCK_STUN_TIMER","3,1");overridden.setProperty("INVIS_CAST_BREAK","true");var changed=CombatRules.snapshot(overridden,damage,p,p);source(changed,overridden);check(changed.equals(CombatRules.nativeSourceSkillDefaultsOriginalSnapshot(overridden,damage,p,p)),"explicit valid overrides retain complete original validation/result");
   for(var entry:List.of(Map.entry("BURNING_CHANCE","101"),Map.entry("BURNING_CHANCE","1.5"),Map.entry("IMMUNE_TO_HARM","0"),Map.entry("IMMUNE_TO_HARM","NaN"),Map.entry("BURNING_DMG","Infinity"),Map.entry("JOY_OF_PAIN_COUNTDMG","0"),Map.entry("CURSE_TIME","-1"),Map.entry("SHOCK_STUN_TIMER","0,1"),Map.entry("SLAY_BREAK_TIMER","70000,0"),Map.entry("MORTAL_BODY_ROM","bad"))){var properties=SourceSkillConfigOracle.properties();properties.setProperty(entry.getKey(),entry.getValue());var before=new Properties();before.putAll(properties);var old=invalid(properties,damage,p,true);var now=invalid(properties,damage,p,false);check(old.getClass()==now.getClass()&&old.getMessage().equals(now.getMessage())&&properties.equals(before)&&state.get(null)==prior,"existing type/range/nonfinite/timer checks and publication refusal preserved "+entry.getKey());safety++;properties.remove("CURSE_READY_TIME");if(!entry.getKey().equals("CURSE_READY_TIME")){invalid(properties,damage,p,false);check(state.get(null)==prior,"filling an optional default does not bypass a different unsafe value");}}
   var badDamage=damage();badDamage.setProperty("AC_REDUCTION_DIVISOR","NaN");invalid(empty,badDamage,p,false);check(state.get(null)==prior,"skill default preparation preserves original damage table validation");safety++;var unknown=SourceSkillConfigOracle.properties();for(var k:List.of("MIRROR","STRIKER_DMG","ILLUSION_AVATAR_DAMAGE")){unknown.setProperty(k,"999");check(!CombatRules.SKILL_KEYS.contains(k)&&NativeSourceSkillDefaults.value(k)==null,"uninstalled Source property does not acquire a new consumer "+k);}unknown.setProperty("NATURES_BLESSING_HEAL","999");check(CombatRules.snapshot(unknown,damage,p,p).values().equals(original.values()),"Source declared-only/unassigned Nature field still remains0 and unused controls stay inactive");
   state.set(null,defaults);check(CombatRules.intField(0,146,"manaGain")==12,"original material skill mana adapter consumes default12");check(CombatRules.intField(0,33,"warningDelayMillis")==5000&&CombatRules.intField(0,33,"paralysisDurationMillis")==10000,"original curse timer adapter consumes Source defaults");check(CombatRules.intField(0,87,"baseStunSeconds")==2&&CombatRules.intField(0,87,"randomStunSeconds")==2,"original stun timer adapter consumes Source defaults");check(CombatRules.intField(0,192,"minimumBindSeconds")==4&&CombatRules.intField(0,192,"maximumBindSeconds")==4,"original bind adapter consumes Source default interval");check(CombatRules.intField(0,77,"specialCriticalChancePercent")==40&&CombatRules.intField(0,77,"specialCriticalGfx")==11748,"original critical control adapter consumes Source defaults");check(CombatRules.protectedDamage(9)==4&&CombatRules.doubleField(0,91,"damageMultiplier")==1.5,"original damage/reaction adapters consume validated Source defaults");check(omissions==31&&blanks==62&&safety==11&&NativeSourceSkillDefaults.class.getDeclaredFields().length==0,"all installed keys and original safety gates, without global state or SQL");
  }finally{state.set(null,prior);}check(state.get(null)==prior,"original control snapshot restored");System.out.println("PASS"+cases+" installed Source skill omission/blank/default/original-safety contracts; omitted="+omissions+", blank="+blanks+", original-safety="+safety+", frozen-Source-values="+compared+"; all Source config semantics/backend/Main/game/MySQL remain open");
 }
}
